  comps: { mod: "Utiliser un modèle ou une simulation", lire: "Lire et exploiter des données", calc: "Calculer des fréquences et des probabilités", conn: "Mobiliser ses connaissances", crit: "Confronter un modèle à la réalité", rais: "Raisonner, argumenter" },
  vers: { g: { icon: "🧭", short: "Guidée", name: "Version guidée", q: "guidee", desc: "Je réponds par des choix, des tableaux à cocher et des valeurs calculées ou lues dans les simulations, avec des pistes pas à pas." },
    l: { icon: "🎓", short: "Exigeante", name: "Version exigeante", q: "exigeante", desc: "Les mêmes manipulations, mais je calcule davantage, je démontre et je rédige mes réponses : je vois → je sais → j'en déduis." } },
  extraTitle: "Mes simulations",
  extra: () => { const R = fruns(), c = gm(), T = gTot();
    return `LE BAL DES GAMÈTES (${fmt(T)} fécondations simulées)\n` + (T ? `- (A//A) : ${c[0]} (f = ${f3(c[0] / T)}) · (A//a) : ${c[1] + c[2]} (f = ${f3((c[1] + c[2]) / T)}) · (a//a) : ${c[3]} (f = ${f3(c[3] / T)})` : "- aucune") +
      `\n\nLE LABO DES FORCES ÉVOLUTIVES (${R.length} simulation${R.length > 1 ? "s" : ""})\n` + (R.length ? R.map(r => `- n° ${r.id} : ${forceTxt(r)} → p = ${f2(r.ps[9])} à la génération 10, ${f2(r.ps[NG - 1])} à la génération 30`).join("\n") : "- aucune") + "\n"; },
