const W_SQ = { title: "Manipulation · Le carré de Hardy-Weinberg", w: "sq" };
const W_GEN = { title: "Tableur · Génération après génération", w: "gen" };
const W_OBS = { title: "Graphique · Le modèle face aux observations", w: "obs" };
const W_FS = { title: "Simulateur · Le labo des forces évolutives (sélection)", w: "forsel", sim: "Valeurs simulées" };
const W_FA = { title: "Simulateur · Le labo des forces évolutives (toutes les forces)", w: "forall", sim: "Valeurs simulées" };
const W_MN = { title: "Comparateur · Effectifs observés et attendus (groupes MN)", w: "cmpmn" };
const W_HB = { title: "Comparateur · Effectifs observés et attendus (hémoglobine)", w: "cmphb" };
const DOC_PAON = { title: "Document 1 · L'araignée paon et ses « bumps »", html: `<p>L'araignée paon <i>Maratus volans</i> vit en Australie et mesure environ 5 mm. Pendant la parade nuptiale, le mâle déploie son abdomen très coloré (bleu, rouge, orange ou jaune) pour attirer les femelles ; l'abdomen des femelles est brun et discret.</p><p>En 2019, des chercheurs ont montré que les taches noires de l'abdomen sont dues à de minuscules reliefs, les « bumps », qui absorbent presque toute la lumière : plus ils sont développés, plus le contraste avec les couleurs est fort, et plus le mâle séduit les femelles.</p><p>On s'intéresse à un gène qui intervient dans la formation des bumps. Il possède deux allèles : <b>A</b> (contraste élevé) et <b>a</b> (contraste faible). Les mâles (A//A) sont plus contrastés que les (A//a), eux-mêmes plus contrastés que les (a//a).</p>`, cap: "D'après le manuel (doc. 3 p. 193). Le gène et ses deux allèles sont un modèle simplifié pour l'activité." };
const DOC_METH = { title: "Document 2 · Point méthode : calculer des fréquences", html: `<ul class="ul"><li><b>Fréquence génotypique</b> : f(génotype) = nombre d'individus de ce génotype ÷ nombre total d'individus N.</li><li><b>Fréquence allélique</b> : f(allèle) = nombre de copies de cet allèle ÷ nombre total d'allèles, soit <b>2N</b> : chaque individu porte deux allèles du gène, un sur chaque chromosome de la paire.</li><li>Notations : f(A) = <b>p</b> ; f(a) = <b>q</b>. Le gène n'ayant que deux allèles : <b>p + q = 1</b>.</li><li>Autre méthode : un (A//A) porte deux allèles A, un (A//a) n'en porte qu'un sur deux, d'où <b>f(A) = f(A//A) + ½ f(A//a)</b>.</li></ul><div class="box warn"><p class="lab">⚠ Ne pas confondre</p><p>Fréquence génotypique (on compte des individus) et fréquence allélique (on compte des allèles).</p></div>` };
const DOC_HW = { title: "Document 3 · Le modèle de Hardy-Weinberg (1908)", html: `<p>En 1908, le mathématicien anglais Godfrey H. Hardy (1877-1947) et le médecin allemand Wilhelm Weinberg (1862-1937) montrent, chacun de son côté, comment calculer la composition génétique d'une génération à partir de la précédente.</p><p>Le modèle décrit une population <b>idéale</b> : de très grand effectif, où les gamètes se rencontrent <b>au hasard</b>, sans mutation, sans sélection et sans migration.</p><p>Chaque gamète ne porte qu'un allèle du gène : il porte A avec la probabilité p, et a avec la probabilité q. Ovule et spermatozoïde se rencontrant au hasard, la probabilité d'un génotype est le <b>produit</b> des probabilités des deux gamètes : on la calcule dans un <b>tableau de croisement</b>.</p>` };
const DOC_OBS = { title: "Document 4 · Le suivi d'une population d'araignées paon", html: `<p>Des chercheurs ont suivi une population d'araignées paon pendant 10 générations. À chaque génération, ils ont mesuré la fréquence p de l'allèle A (graphique et tableau ci-dessous). À la génération 1, p = 0,40, comme dans la population étudiée dans les parties 1 et 2.</p>`, cap: "Données du manuel (doc. 3 p. 193)." };
const DOC_HAND = { title: "Document 5 · La théorie du handicap", html: `<p>Certains caractères voyants, comme l'abdomen coloré des mâles de <i>M. volans</i>, coûtent cher à leur porteur : ils demandent de l'énergie et attirent l'attention des prédateurs. On s'attendrait donc à ce qu'ils disparaissent. Pourtant, les femelles préfèrent souvent les mâles qui les portent.</p><p>En 1975, le zoologiste israélien Amotz Zahavi propose une explication : survivre malgré ce « handicap » montre que le mâle est de bonne qualité. Chaque mâle est donc pris entre deux exigences opposées : être discret pour survivre plus longtemps, ou être voyant pour attirer les femelles. Son succès dépend d'un équilibre entre les deux.</p>`, cap: "D'après le manuel (doc. 4 p. 193), reformulé." };
const DOC_LAB = { title: "Document 6 · Les réglages du labo des forces évolutives", html: `<p>Le labo part de p = 0,40 à la génération 1. À chaque génération, les gamètes se rencontrent au hasard (p², 2pq, q²), puis les forces choisies modifient les fréquences.</p>${tbl(["Génotype", "Sélection sexuelle : succès reproducteur relatif", "Prédation : survie relative"], [["(a//a)", "× 1", "1"], ["(A//a)", "× 2,4", "0,8"], ["(A//A)", "× 3", "0,55"]])}<p class="cap">Exemple : un mâle (A//A) laisse en moyenne 3 fois plus de descendants qu'un (a//a), mais il a 45 % de risques en plus d'être mangé avant de se reproduire.</p>`, cap: "⚠ Valeurs d'un modèle simplifié, choisies pour être compatibles avec les observations du manuel." };
const DOC_MN = { title: "Document 7 · Les groupes sanguins M et N", html: `<p>Le système MN, découvert en 1927, est un système de groupes sanguins moins connu que le système ABO. Il dépend d'un gène à deux allèles, <b>M</b> et <b>N</b>, qui s'expriment tous les deux : une analyse de sang donne directement le génotype (M//M), (M//N) ou (N//N).</p><p>Ce groupe sanguin n'a pas d'effet connu sur la santé, et personne ne choisit son partenaire selon son groupe MN.</p><p>Dans un échantillon de <b>1 000 personnes</b> : <b>292 (M//M)</b>, <b>496 (M//N)</b> et <b>212 (N//N)</b>.</p>`, cap: "⚠ Effectifs ramenés à 1 000 personnes, d'après une étude classique de génétique des populations." };
const DOC_HB = { title: "Document 8 · Drépanocytose et paludisme", html: `<p>Le gène de l'hémoglobine (la protéine des globules rouges qui transporte le dioxygène) possède notamment deux allèles : <b>A</b> (hémoglobine normale) et <b>S</b>.</p><ul class="ul"><li><b>(S//S)</b> : drépanocytose, une anémie grave ; sans traitement, la plupart des malades meurent avant l'âge adulte.</li><li><b>(A//S)</b> : en général en bonne santé, et mieux protégés que les (A//A) contre les formes graves du paludisme.</li><li><b>(A//A)</b> : pas de drépanocytose, mais pas de protection particulière contre le paludisme.</li></ul><p>Dans une région d'Afrique de l'Ouest où le paludisme est très fréquent, on a déterminé le génotype de <b>1 000 adultes</b> : <b>671 (A//A)</b>, <b>328 (A//S)</b> et <b>1 (S//S)</b>.</p>`, cap: "⚠ Effectifs ramenés à 1 000 adultes, d'après une étude classique menée au Nigeria. Le paludisme est une maladie due à un parasite transmis par des moustiques." };
const DOC_R = { title: "Document 9 · Mes résultats", w: "recap" };

/* ---------- bilan à recopier (synthèse du professeur, complétée) ---------- */
const BIL = [
  "<u>Fréquence génotypique</u> = effectif d'un génotype ÷ effectif total N. <u>Fréquence allélique</u> = nombre de copies d'un allèle ÷ nombre total d'allèles (<u>2N</u>, car chaque individu porte deux allèles). Pour un gène à deux allèles A et a : f(A) = p, f(a) = q, <u>p + q = 1</u>, et f(A) = f(A//A) + ½ f(A//a).",
  "<u>Modèle de Hardy-Weinberg</u> (1908) : dans une population de très grand effectif, où les gamètes se rencontrent au hasard, sans mutation, sans sélection, sans migration et sans dérive, un tableau de croisement donne les fréquences génotypiques de la génération suivante : la fréquence d'un homozygote est <u>p²</u>, celle de l'autre homozygote est <u>q²</u>, celle de l'hétérozygote est <u>2pq</u>, avec <u>p² + 2pq + q² = (p + q)² = 1</u>.",
  "Une population idéale respecte l'<u>équilibre de Hardy-Weinberg</u> : les fréquences <u>alléliques</u> et <u>génotypiques</u> restent les mêmes d'une génération à l'autre (f(A) = p² + pq = p), dès la 2ᵉ génération. La population n'évolue pas.",
  "Une population qui ne respecte pas cet équilibre <u>évolue</u>. Mécanismes possibles : elle subit des <u>mutations</u> (nouveaux allèles, effet lent) ; la <u>sélection sexuelle</u> : l'accouplement ne se fait pas au hasard ; la <u>sélection naturelle</u> : certains allèles sont favorisés par rapport à d'autres ; la <u>dérive génétique</u> : variation aléatoire des fréquences alléliques, d'autant plus forte que la population est petite ; les <u>migrations</u> : elles augmentent les flux génétiques entre populations.",
  "Exemple : chez l'araignée paon, f(A) passe de 0,40 à 0,69 en 10 générations : la population évolue. La <u>sélection sexuelle</u> favorise les mâles contrastés, la <u>prédation</u> (sélection naturelle) les défavorise : ce compromis stabilise la fréquence de A."];
const bilanHTML = () => BIL.map(x => `<p>${nb(x)}</p>`).join("");

/* ---------- critères de repérage communs (réponses rédigées) ---------- */
const hasAA = T => /\(? ?A ?\/\/ ?A ?\)?|\bAA\b/.test(T), hasaa = T => /a ?\/\/ ?a\b|\baa\b/.test(T.replace(/A ?\/\/ ?a/g, "")), hasAa = T => /A ?\/\/ ?a|\bAa\b/.test(T);
const P2 = /(p ?²|p ?\^ ?2|p2\b|p ?(×|\*|x) ?p)/;
const FORCES = ["mutation", "selection naturelle", "selection sexuelle", "derive", "migration"];

